#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int *head, *to, *next_edge;
static int *stack_node, *stack_parent, *stack_depth;

static int bfs(int n, int source, int *dist, int *parent) {
    int *queue = (int *)malloc((size_t)n * sizeof(int));
    for (int i = 0; i < n; i++) {
        dist[i] = -1;
        parent[i] = -1;
    }

    int front = 0, back = 0;
    queue[back++] = source;
    dist[source] = 0;
    int farthest = source;

    while (front < back) {
        int u = queue[front++];
        if (dist[u] > dist[farthest]) {
            farthest = u;
        }

        for (int e = head[u]; e != -1; e = next_edge[e]) {
            int v = to[e];
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                parent[v] = u;
                queue[back++] = v;
            }
        }
    }

    free(queue);
    return farthest;
}

static long long count_at_distance(int start, int forbidden, int initial_depth,
                                   int target_depth) {
    int top = 0;
    stack_node[top] = start;
    stack_parent[top] = forbidden;
    stack_depth[top++] = initial_depth;

    long long count = 0;

    while (top > 0) {
        --top;
        int u = stack_node[top];
        int parent = stack_parent[top];
        int depth = stack_depth[top];

        if (depth == target_depth) {
            count++;
            continue;
        }

        for (int e = head[u]; e != -1; e = next_edge[e]) {
            int v = to[e];
            if (v != parent) {
                stack_node[top] = v;
                stack_parent[top] = u;
                stack_depth[top++] = depth + 1;
            }
        }
    }

    return count;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    head = (int *)malloc((size_t)n * sizeof(int));
    to = (int *)malloc((size_t)(2 * (n - 1)) * sizeof(int));
    next_edge = (int *)malloc((size_t)(2 * (n - 1)) * sizeof(int));
    stack_node = (int *)malloc((size_t)n * sizeof(int));
    stack_parent = (int *)malloc((size_t)n * sizeof(int));
    stack_depth = (int *)malloc((size_t)n * sizeof(int));

    for (int i = 0; i < n; i++) {
        head[i] = -1;
    }

    int edge_count = 0;
    for (int i = 0; i < n - 1; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        --x;
        --y;

        to[edge_count] = y;
        next_edge[edge_count] = head[x];
        head[x] = edge_count++;

        to[edge_count] = x;
        next_edge[edge_count] = head[y];
        head[y] = edge_count++;
    }

    int *dist = (int *)malloc((size_t)n * sizeof(int));
    int *parent = (int *)malloc((size_t)n * sizeof(int));

    int endpoint_a = bfs(n, 0, dist, parent);
    int endpoint_b = bfs(n, endpoint_a, dist, parent);
    int diameter = dist[endpoint_b];

    int *path = (int *)malloc((size_t)(diameter + 1) * sizeof(int));
    int current = endpoint_b;
    for (int i = diameter; i >= 0; i--) {
        path[i] = current;
        current = parent[current];
    }

    long long ways = 0;

    if (diameter % 2 == 0) {
        int radius = diameter / 2;
        int center = path[radius];
        long long total = 0;
        long long sum_squares = 0;

        for (int e = head[center]; e != -1; e = next_edge[e]) {
            int branch_count = (int)count_at_distance(to[e], center, 1, radius);
            total += branch_count;
            sum_squares += (long long)branch_count * branch_count;
        }

        ways = (total * total - sum_squares) / 2;
    } else {
        int radius = diameter / 2;
        int center_a = path[radius];
        int center_b = path[radius + 1];

        long long count_a = count_at_distance(center_a, center_b, 0, radius);
        long long count_b = count_at_distance(center_b, center_a, 0, radius);
        ways = count_a * count_b;
    }

    printf("%d\n%lld\n", diameter + 1, ways);

    free(path);
    free(dist);
    free(parent);
    free(head);
    free(to);
    free(next_edge);
    free(stack_node);
    free(stack_parent);
    free(stack_depth);

    return 0;
}
